mapper.select:
select follower_id, notify_new_content
from follows
where following_id = #{authorUserId}
  and muted = false
  and follower_id > #{cursor}

  and notify_new_content = true

order by follower_id
limit #{limit}

mapper.insert:
insert into user_feed_entries (
    user_id, content_id, author_user_id, source_event_id, score
)
select #{userId}, #{contentId}, #{authorUserId}, #{sourceEventId}, #{score}
where not exists (
    select 1
    from user_feed_entries
    where user_id = #{userId}
      and content_id = #{contentId}
)
